CREATE EXTENSION IF NOT EXISTS btree_gist;
CREATE TABLE app_user (user_id uuid PRIMARY KEY, email varchar(320) NOT NULL UNIQUE, password_hash varchar(255) NOT NULL, status varchar(32) NOT NULL CHECK(status IN ('PENDING_VERIFICATION','ACTIVE','DEACTIVATED')), created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE department (department_id uuid PRIMARY KEY, name varchar(120) NOT NULL UNIQUE, active boolean NOT NULL DEFAULT true, timezone varchar(64) NOT NULL, created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE doctor (doctor_id uuid PRIMARY KEY, user_id uuid NOT NULL UNIQUE REFERENCES app_user(user_id), doctor_number varchar(40) NOT NULL UNIQUE, department_id uuid NOT NULL REFERENCES department(department_id), verification_status varchar(32) NOT NULL CHECK(verification_status IN ('PENDING','APPROVED','REJECTED')), active boolean NOT NULL DEFAULT false);
CREATE TABLE patient (patient_id uuid PRIMARY KEY, user_id uuid NOT NULL UNIQUE REFERENCES app_user(user_id), patient_number varchar(40) NOT NULL UNIQUE, full_name varchar(160) NOT NULL, date_of_birth date, created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE appointment (appointment_id uuid PRIMARY KEY, appointment_number varchar(40) NOT NULL UNIQUE, patient_id uuid NOT NULL REFERENCES patient(patient_id), doctor_id uuid NOT NULL REFERENCES doctor(doctor_id), starts_at timestamptz NOT NULL, ends_at timestamptz NOT NULL, status varchar(32) NOT NULL CHECK(status IN ('REQUESTED','CONFIRMED','CHECKED_IN','IN_PROGRESS','COMPLETED','CANCELLED','RESCHEDULED','NO_SHOW')), created_at timestamptz NOT NULL DEFAULT now(), CHECK(ends_at > starts_at));
ALTER TABLE appointment ADD CONSTRAINT no_overlapping_active_doctor_appointment EXCLUDE USING gist (doctor_id WITH =, tstzrange(starts_at,ends_at,'[)') WITH &&) WHERE (status IN ('REQUESTED','CONFIRMED','CHECKED_IN','IN_PROGRESS'));
CREATE INDEX appointment_patient_idx ON appointment(patient_id, starts_at DESC);
CREATE INDEX appointment_doctor_idx ON appointment(doctor_id, starts_at);
CREATE INDEX appointment_status_idx ON appointment(status, starts_at);
CREATE TABLE audit_log (audit_log_id uuid PRIMARY KEY, actor_id uuid, action varchar(100) NOT NULL, resource_type varchar(100) NOT NULL, resource_id uuid, occurred_at timestamptz NOT NULL DEFAULT now(), request_id varchar(100), result varchar(32) NOT NULL);
CREATE TABLE outbox_event (event_id uuid PRIMARY KEY, event_type varchar(120) NOT NULL, aggregate_type varchar(100) NOT NULL, aggregate_id uuid NOT NULL, payload jsonb NOT NULL, idempotency_key varchar(180) NOT NULL UNIQUE, occurred_at timestamptz NOT NULL DEFAULT now(), status varchar(20) NOT NULL DEFAULT 'PENDING', attempts integer NOT NULL DEFAULT 0);
CREATE INDEX outbox_pending_idx ON outbox_event(status, occurred_at) WHERE status='PENDING';
